import { atom, read, update } from 'claude-code'
import type { Register } from 'claude-code'

import type { UsageLeftWindow } from '../types'

type SessionRateLimit = UsageLeftWindow

const windows = atom({ plugin: 'usage-left', key: 'windows' } as const, [])
const drawnAt = atom({ plugin: 'usage-left', key: 'now' } as const, 0)

const NONE = 'No usage window reported yet: it comes with the first response, on a subscription plan.'

const leftOf = (window: SessionRateLimit) => Math.max(0, Math.round(100 - window.percentUsed))

/** How long until `iso`, as `2h 14m`, `38m` or `3d 4h`; nothing for a time that has passed or does not parse. */
const until = (iso: string | undefined, now: number) => {
  const ms = iso === undefined ? NaN : Date.parse(iso) - now
  if (!(ms > 0)) return undefined
  const minutes = Math.max(1, Math.round(ms / 60_000))
  const days = Math.floor(minutes / 1440)
  const hours = Math.floor((minutes % 1440) / 60)
  if (days > 0) return `${days}d ${hours}h`

  return hours > 0 ? `${hours}h ${minutes % 60}m` : `${minutes}m`
}

const part = (name: string, window: SessionRateLimit, now: number) => {
  const wait = until(window.resetsAt, now)

  return `${name}: ${leftOf(window)}% left${wait === undefined ? '' : `, resets in ${wait}`}`
}

/**
 * The toast's line: what is left of the five-hour window and when it resets,
 * and the weekly window too once it is the tighter of the two or nearly spent.
 */
const lineOf = (limits: readonly SessionRateLimit[], now: number) => {
  const session = limits.find(w => w.kind === 'five_hour')
  const week = limits.find(w => w.kind === 'seven_day')
  const parts: string[] = []
  if (session !== undefined) parts.push(part('Session', session, now))
  if (week !== undefined && (session === undefined || leftOf(week) <= 25 || leftOf(week) < leftOf(session)))
    parts.push(part('Week', week, now))

  return parts.length === 0 ? undefined : parts.join('  ·  ')
}

/**
 * What the hint line under the prompt ends with: a small meter of the five-hour
 * window, what is left of it and when it resets; the week once it matters.
 */
const tailOf = (limits: readonly SessionRateLimit[], now: number) => {
  const session = limits.find(w => w.kind === 'five_hour')
  const week = limits.find(w => w.kind === 'seven_day')
  const parts: string[] = []
  if (session !== undefined) {
    const left = leftOf(session)
    const filled = Math.round(left / 10)
    const wait = until(session.resetsAt, now)
    parts.push(`${'\u25b0'.repeat(filled)}${'\u25b1'.repeat(10 - filled)} ${left}% left${wait === undefined ? '' : ` \u00b7 resets in ${wait}`}`)
  }
  if (week !== undefined && (session === undefined || leftOf(week) <= 25 || leftOf(week) < leftOf(session)))
    parts.push(`week ${leftOf(week)}%`)

  return parts.length === 0 ? undefined : parts.join(' \u00b7 ')
}

/** A toast marks the session window falling to each of these, percent left. */
const MARKS = [50, 25, 10]

export const register: Register = on => {
  // The lowest mark already toasted in this window; a reset (the figure rising) arms them again.
  let toasted = 101
  let before = 100

  on('session.start', async ($, e, next) => {
    await $.command.register({ name: 'left', description: 'Show how much of the usage window is left' })
    const { rateLimits } = await $.session.usage()
    await update($, windows, () => [...rateLimits])
    const started = await $.clock.now()
    await update($, drawnAt, () => started)
    $.clock.every(60_000, async () => {
      const now = await $.clock.now()
      await update($, drawnAt, () => now)
    })

    return next(e)
  })

  on('session.measure', async ($, e, next) => {
    const now = await $.clock.now()
    await update($, windows, () => [...e.rateLimits])
    await update($, drawnAt, () => now)
    const session = e.rateLimits.find(w => w.kind === 'five_hour')
    if (session !== undefined) {
      const left = leftOf(session)
      if (left > before) toasted = 101
      before = left
      const mark = MARKS.filter(m => left <= m && m < toasted).pop()
      if (mark !== undefined) {
        toasted = mark
        $.ui.toast(lineOf(e.rateLimits, now) ?? '', { timeoutMs: 8000 })
      }
    }

    return next(e)
  })

  on('ui.render', { component: 'PromptHint' }, async ($, e, next) => {
    const tail = tailOf(await read($, windows), await read($, drawnAt))
    if (tail === undefined) return next(e)

    return next({ ...e, props: { ...e.props, tail: e.props.tail === undefined ? tail : `${e.props.tail} \u00b7 ${tail}` } })
  })

  on('command.run', { command: 'left' }, async $ => {
    const { rateLimits } = await $.session.usage()
    const now = await $.clock.now()
    await update($, windows, () => [...rateLimits])
    await update($, drawnAt, () => now)

    return { text: lineOf(rateLimits, now) ?? NONE }
  })
}

