export type UsageLeftWindow = { kind: string; percentUsed: number; resetsAt?: string }

declare module 'claude-code' {
  interface PluginState {
    'usage-left': {
      /** The rate-limit windows as last measured. */
      windows: UsageLeftWindow[]
      /** The time the countdown is drawn for, moved once a minute. */
      now: number
    }
  }
}
